import json, sys

def generate_parentheses(payload):
    n = payload.get("n", 0)
    if n < 0:
        return []
    if n == 0:
        return [""]
    res = []
    def backtrack(cur, open_cnt, close_cnt):
        if len(cur) == 2 * n:
            res.append(cur)
            return
        if open_cnt < n:
            backtrack(cur + '(', open_cnt + 1, close_cnt)
        if close_cnt < open_cnt:
            backtrack(cur + ')', open_cnt, close_cnt + 1)
    backtrack("", 0, 0)
    return res

if __name__ == "__main__":
    payload = json.loads(sys.stdin.read() or "{}")
    print(json.dumps(generate_parentheses(payload), separators=(",", ":")))

import json, sys

def erase_overlap_intervals(payload):
    intervals = payload.get("intervals", [])
    if not intervals:
        return 0
    intervals.sort(key=lambda x: x[1])
    kept = 0
    last_end = -10**18
    for s, e in intervals:
        if s >= last_end:
            kept += 1
            last_end = e
    return len(intervals) - kept

if __name__ == "__main__":
    payload = json.loads(sys.stdin.read() or "{}")
    print(json.dumps(erase_overlap_intervals(payload), separators=(",", ":")))

import sys

def solve():
    s = sys.stdin.read()
    if not s:
        return
    s = s.rstrip('\n')
    # In case there are multiple lines, take the first line as the string
    if '\n' in s:
        s = s.splitlines()[0]
    vowels = set('aeiouAEIOU')
    chars = list(s)
    i, j = 0, len(chars) - 1
    while i < j:
        while i < j and chars[i] not in vowels:
            i += 1
        while i < j and chars[j] not in vowels:
            j -= 1
        if i < j:
            chars[i], chars[j] = chars[j], chars[i]
            i += 1
            j -= 1
    sys.stdout.write(''.join(chars))

if __name__ == "__main__":
    solve()

